{
  "case_id": "xsu_sg_011_doctor_certificate",
  "criteria": {
    "c01_overall_legal_correctness": {
      "label": "met",
      "reason": "Svaret gengiver korrekt, at Udbetaling Danmark kan indhente lægeattest fra den praktiserende læge, når funktionsniveauet ikke kan vurderes. Det gengiver også korrekt attestens indhold, fremmøde som udgangspunkt, journaloplysninger i særlige tilfælde og at styrelsen afholder udgifterne. Ingen af rubrikkens materielle fejl forekommer."
    },
    "c02_required_elements_complete": {
      "label": "met",
      "reason": "Alle tre kritiske elementer er med: muligheden for at indhente lægeattest fra praktiserende læge, funktionsevne i forhold til den søgte funktionsnedsættelse og behov for fortsat behandling eller henvisning til yderligere udredning eller specialistbehandling."
    },
    "c03_direct_relevance": {
      "label": "met",
      "reason": "Svaret besvarer begge dele af spørgsmålet: hvad Udbetaling Danmark kan gøre, og hvad lægeattesten skal beskrive."
    },
    "c04_source_traceability": {
      "label": "not_met",
      "reason": "Svaret angiver ingen identificerbar kilde, f.eks. vejledningens afsnit 5.1.2 eller en bestemmelse. Ifølge reglen er C04 derfor not_met."
    },
    "c05_source_validity": {
      "label": "not_assessable",
      "reason": "Der er ikke angivet nogen kilde, så kildens gyldighed kan ikke vurderes."
    },
    "c06_claim_source_support": {
      "label": "not_assessable",
      "reason": "Der er ikke angivet nogen kilde, så det kan ikke vurderes, om en kilde understøtter påstandene."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "met",
      "reason": "Alle udsagn har støtte i vejledningens afsnit 5.1.2: lægeattest, journaloplysninger i særlige tilfælde, fremmøde som udgangspunkt og udgifter afholdt af styrelsen. Svaret tilføjer ingen ustøttede regler."
    },
    "c08_qualifications_and_exceptions": {
      "label": "met",
      "reason": "Svaret bevarer 'kan' for attestindhentning, 'i særlige tilfælde' for journaloplysninger og 'som udgangspunkt' for fremmøde. Det gør ikke attestindhentning til en automatisk pligt."
    },
    "c09_reasoning_coherence": {
      "label": "met",
      "reason": "Svaret er sammenhængende og uden modstrid: først muligheden for at indhente lægeattest, derefter attestens indhold og de supplerende forhold."
    },
    "c10_legal_modality_precision": {
      "label": "met",
      "reason": "Modaliteten er præcis: 'kan' indhente, 'skal' beskrive (attestens indhold), 'som udgangspunkt' for fremmøde og 'i særlige tilfælde' for journaloplysninger. Det følger kilden. Formuleringen 'ansøgeren skal som udgangspunkt møde op' svarer til kildens medvirkenskrav og fremmøde som udgangspunkt."
    }
  },
  "xhaile_coverage": {
    "A61": {
      "label": "yes",
      "reason": "Svaret dækker alle led i punktet: lægeattest kan indhentes, når funktionsniveauet ikke kan vurderes, attestens indhold (funktionsevne og behov for behandling eller henvisning), fremmøde som udgangspunkt, yderligere journaloplysninger i særlige tilfælde og at styrelsen afholder udgifterne. Kravet om, at ansøgeren skal medvirke, er kun gengivet via fremmødeudsagnet, men det er dækkende."
    }
  },
  "overall_notes": "Indholdsmæssigt korrekt og fuldstændigt svar uden kildeangivelse. Derfor er C04 not_met, mens C05 og C06 er not_assessable efter kilderegelen."
}

